import subprocess, re, os, collections, glob
repo = r'C:\Users\JJ\Documents\Proyecto predeterminado'
EXP = os.path.join(repo,'ultrakill-webport','export','ExportedProject')
ASSETS = os.path.join(EXP,'Assets')

def blob(rev, f):
    r = subprocess.run(['git','-C',repo,'show',rev+':'+f], capture_output=True, text=True, encoding='utf8', errors='replace')
    return r.stdout

# gather shader guids (from worktree .meta next to .shader) -> path
guid2path = {}
for root,_,fs in os.walk(ASSETS):
    for fn in fs:
        if fn.endswith('.shader.meta'):
            p = os.path.join(root,fn).replace('.meta','')
            mp = os.path.join(root,fn)
            name = blob_between = open(mp,encoding='utf8',errors='replace').read()
            m = re.search(r'guid: ([0-9a-f]{32})',name)
            if m: guid2path[m.group(1)] = p

allsh = subprocess.run(['git','-C',repo,'ls-files'],capture_output=True,text=True).stdout.splitlines()
shader_paths = [f for f in allsh if f.endswith('.shader')]
real_paths, dummy_paths = set(), set()
for f in shader_paths:
    txt = blob('0ad206b54',f)
    (dummy_paths if 'DummyShaderTextExporter' in txt else real_paths).add(f)

def rb(p):
    r = subprocess.run(['git','-C',repo,'show','0ad206b54:'+p],capture_output=True,text=True,encoding='utf8',errors='replace')
    return r.stdout

# path -> guid via meta in git
path2guid = {}
for f in shader_paths:
    m = glob2 = re.search(r'guid: ([0-9a-f]{32})', rb(f+'.meta') or '')
    if m: path2guid[f] = m.group(1)
real_guids = {path2guid[f] for f in real_paths if f in path2guid}
dummy_guids = {path2guid[f] for f in dummy_paths if f in path2guid}
print('real shader guids:', len(real_guids), ' dummy guids:', len(dummy_guids))

# scan .mat files for TW value + shader guid + name
mats = [f for f in allmats_all] if False else None
allmatfiles = [f for f in subprocess.run(['git','-C',repo,'ls-files'],capture_output=True,text=True).stdout.splitlines() if f.endswith('.mat')]
cnt = collections.Counter()
examples = {'real_TW1': [], 'real_TW1_names': collections.Counter()}
unknown=[]
for f in allmatfiles:
    txt = blob('0ad206b54',f)
    if '_TextureWarping' not in txt: continue
    tvals = re.findall(r'_TextureWarping: ([\d.\-]+)', txt)
    vvals = re.findall(r'_VertexWarping: ([\d.\-]+)', txt)
    g = re.search(r'm_Shader: \{fileID: \d+, guid: ([0-9a-f]{32})', txt)
    guid = g.group(1) if g else None
    nme = re.search(r'guid: ([0-9a-f]{32})', txt.split('m_Shader:')[0] if g else '')
    if not tvals: continue
    assert len(tvals)==1
    key = (tvals[0], vvals[0] if vvals else '-')
    if key==('0','9999'):
        kind = 'neutral'
    else:
        kind = 'TW%s_VW%s @ %s' % (tvals[0], vvals[0] if vvals else '-', 'REAL' if guid in real_guids else ('dummy' if guid in dummy_guids else 'OTHERGUID'))
    cnt[kind]+=1
    if guid in real_guids:
        examples['real_TW1_names'][key]+=1
for k,v in cnt.most_common(): print('  ', k, v)
print('REAL-shader mats with non-neutral:', sum(v for k,v in examples['real_TW1_names'].items()))
for k,v in examples['real_TW1_names'].most_common(): print('   ',k,v)

