import subprocess, re, collections, os
repo = r'C:\Users\JJ\Documents\Proyecto predeterminado'
ASSETS = os.path.join(repo,'ultrakill-webport','export','ExportedProject','Assets')

def rb(rev, f):
    return subprocess.run(['git','-C',repo,'show',rev+':'+f],capture_output=True,text=True,encoding='utf8',errors='replace').stdout

allsh2 = [f for f in subprocess.run(['git','-C',repo,'ls-files'],capture_output=True,text=True).stdout.splitlines() if f.endswith('.shader')]
dummyset, realset = set(), set()
for f in allsh2:
    txt = rb('0ad206b54',f)
    (dummyset if 'DummyShaderTextExporter' in txt else realset).add(f)
dirreal = {os.path.basename(f) for f in realset}
dirdummy = {os.path.basename(f) for f in dummyset}

guid2basename = {}
for root,_,fs in os.walk(ASSETS):
    for fn in fs:
        if fn.endswith('.shader.meta'):
            with open(os.path.join(root,fn),encoding='utf8',errors='replace') as fh:
                m = re.search(r'guid: ([0-9a-f]{32})', fh.read())
            if m:
                guid2basename[m.group(1)] = fn[:-11]   # strip .shader.meta

def kind(guid):
    bn = guid2basename.get(guid)
    if bn in dirreal and bn not in dirdummy: return 'real'
    if bn in dirdummy and bn not in dirreal: return 'dummy'
    if bn in dirreal and bn in dirdummy: return 'AMBIG:'+bn
    return 'unknown:'+ (guid[:8] if guid else '')

allmatfiles = [f for f in subprocess.run(['git','-C',repo,'ls-files'],capture_output=True,text=True).stdout.splitlines() if f.endswith('.mat')]
rows = []
for f in allmatfiles:
    txt = rb('0ad206b54',f).replace('\r\n','\n')
    tw = next(iter(re.findall(r'_TextureWarping: (-?[\d.]+)', txt)), None)
    vw = next(iter(re.findall(r'_VertexWarping: (-?[\d.]+)', txt)), None)
    if 'm_Shader' in txt:
        m = re.search(r'm_Shader: \{fileID: (\d+), guid: ([0-9a-f]{32})', txt)
        guid = m.group(2) if m else None
        fid = m.group(1) if m else None
        sh = kind(guid) if guid else 'nosha-guid'
    else:
        guid, sh, fid = None, 'noshader', None
    anomalous = (tw is not None and tw != '0') or (vw is not None and vw != '9999')
    if anomalous:
        rows.append((f.split('ExportedProject/Assets/')[-1], tw, vw, sh, fid))

print('anomalous-key materials:', len(rows))
kindcnt = collections.Counter(r[3] for r in rows)
print('by kind:', dict(kindcnt))
if 'AMBIG:' in str(list(kindcnt)):
    pass
unknown = [r for r in rows if r[3].startswith('unknown')]
print('unknown-guid sample:')
for r in unknown[:16]: print('   ', r)
real_rows = [r for r in rows if r[3]=='real']
print('real-shader anomalous:', len(real_rows))
folders = collections.Counter(os.path.dirname(r[0]) for r in real_rows)
for k,v in folders.most_common(12): print('  ', v, k)
vwvals = collections.Counter((r[1],r[2]) for r in real_rows)
print('(TW,VW) combos on real:', dict(vwvals))

import subprocess, re, collections, os
repo = r'C:\Users\JJ\Documents\Proyecto predeterminado'

def rbt(rev,f):
    return subprocess.run(['git','-C',repo,'show',rev+':'+f],capture_output=True,text=True,encoding='utf8',errors='replace').stdout

files = subprocess.run(['git','-C',repo,'diff-tree','-r','--name-only','0ad206b54^','0ad206b54'],capture_output=True,text=True).stdout.splitlines()
real = [f for f in files if f.endswith('.shader')]

bad_snap, bad_quant, extra = [], [], []
for f in real:
    t = rbt('0ad206b54',f).replace('\r\n','\n')
    nsnap_floor = len(re.findall(r'floor\(gridX', t))
    guard = t.count('if (_ResY > 0.5)')
    quant = t.count('floor(color.rgb * prec) / prec')
    if nsnap_floor > 0 and nsnap_floor != guard: bad_snap.append((f.split('Assets/')[-1], nsnap_floor, guard))
    if quant != 1: bad_quant.append((f.split('Assets/')[-1], quant))
    # any other degrade patterns
    for pat, label in [(r'\bdither|Dither','dither'), (r'\btrunc\(', 'trunc'), (r'\bround\(', 'round'), (r'floor\((?!color\.rgb|gridX|_ResY)','','other-floor')]:
        hits = re.findall(pat, t)
        if hits: extra.append((f.split('Assets/')[-1], label, len(hits)))
print('vertex snapping unguarded:', len(bad_snap))
for b in bad_snap: print('   ', b)
print('quantization block missing/extra:', len(bad_quant))
for b in bad_quant: print('   ', b)
print('other degrade patterns:')
for e in extra: print('   ', e)

